function fill(template, vars) {
  return template.replace(/\{(\w+)\}/g, (m, k) => (vars && vars[k] !== undefined && vars[k] !== null ? String(vars[k]) : m));
}

function t(key, language, vars) {
  const set = TEMPLATES[key];
